{
  "name": "opencode-auto-title-fallback",
  "version": "0.1.1",
  "description": "OpenCode plugin that uses an LLM fallback to patch default New session titles when the built-in title agent skips.",
  "type": "module",
  "license": "MIT",
  "author": "Mingjian Shao",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "title",
    "llm"
  ],
  "exports": {
    ".": "./dist/index.js"
  },
  "bin": {
    "opencode-auto-title-fallback-install": "dist/install.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "check": "tsc -p tsconfig.json --noEmit",
    "prepare": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/node": "^25.9.1",
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  }
}
